def append_used(path, lines):
    txt=open(path,encoding='utf-8').read()
    add=''.join('- Used by: '+l+'\n' for l in lines)
    if '## Used by' in txt:
        head,sep,tail=txt.partition('## Used by')
        # insert after the section header line and any existing lines directly following
        tail_lines=tail.split('\n')
        # find end of contiguous block after header
        i=1
        while i<len(tail_lines) and tail_lines[i].strip()!='' : i+=1
        new_tail='\n'.join(tail_lines[:i])+'\n'+add+'\n'.join(tail_lines[i:])
        txt=head+sep+new_tail
    else:
        if not txt.endswith('\n'): txt+='\n'
        txt+='\n## Used by\n'+add
    open(path,'w',encoding='utf-8').write(txt)
created=[];appended=[];missing=[]
for slug,(name,meas,metric,oss,run,urls,desc,used) in EV.items():
    p=os.path.join(E,slug+'.md')
    if os.path.exists(p):
        append_used(p,used); appended.append(slug)
    else:
        open(p,'w',encoding='utf-8').write(tpl(name,slug,meas,metric,oss,run,urls,desc,used)); created.append(slug)
for slug,used in APPEND.items():
    p=os.path.join(E,slug+'.md')
    if os.path.exists(p): append_used(p,used); appended.append(slug)
    else: missing.append(slug)
print("CREATED",len(created),created); print("APPENDED",len(appended),appended); print("MISSING(not created)",missing)
